<script>
const cardData=@json($cardData);
document.querySelectorAll('[data-format]').forEach(button=>button.addEventListener('click',async()=>{const card=document.getElementById('ktaCard');const scale=3;const canvas=document.createElement('canvas');const rect=card.getBoundingClientRect();canvas.width=Math.round(rect.width*scale);canvas.height=Math.round(rect.height*scale);const context=canvas.getContext('2d');context.scale(scale,scale);const gradient=context.createLinearGradient(0,0,rect.width,rect.height);gradient.addColorStop(0,'#123b45');gradient.addColorStop(.58,'#123b45');gradient.addColorStop(.58,'#176d67');gradient.addColorStop(1,'#176d67');context.fillStyle=gradient;context.fillRect(0,0,rect.width,rect.height);const photo=card.querySelector('.kta-photo:not([hidden])');let textX=32;if(photo&&!photo.classList.contains('kta-placeholder')){try{const image=new Image();image.src=photo.src;await image.decode();const box=photo.getBoundingClientRect();const x=box.left-rect.left,y=box.top-rect.top;context.drawImage(image,x,y,box.width,box.height);textX=x+box.width+28;}catch{}}else if(photo){const box=photo.getBoundingClientRect();const x=box.left-rect.left,y=box.top-rect.top;context.fillStyle='#e9f1ee';context.fillRect(x,y,box.width,box.height);context.fillStyle='#285d5b';context.font=`${Math.min(64,box.width*.6)}px sans-serif`;context.fillText('●',x+box.width*.28,y+box.height*.62);textX=x+box.width+28;}const logoElement=card.querySelector('.kta-brand img');const logoBox=logoElement.getBoundingClientRect();const logoX=logoBox.left-rect.left,logoY=logoBox.top-rect.top;try{const logo=new Image();logo.src=logoElement.src;await logo.decode();context.save();context.beginPath();context.arc(logoX+logoBox.width/2,logoY+logoBox.height/2,logoBox.width/2,0,Math.PI*2);context.clip();context.drawImage(logo,logoX,logoY,logoBox.width,logoBox.height);context.restore();}catch{}context.fillStyle='#fff';context.font='bold 26px sans-serif';context.fillText(cardData.title,logoX+logoBox.width+18,logoY+logoBox.height/2+9,{maxWidth:rect.width-logoX-logoBox.width-38});const info=card.querySelector('.kta-info').getBoundingClientRect();let y=info.top-rect.top+36;context.fillStyle='#fff';context.font='bold 36px sans-serif';context.fillText(cardData.name,textX,y,{maxWidth:rect.width-textX-24});if(cardData.nickname){y+=27;context.fillStyle='#cce8e0';context.font='16px sans-serif';context.fillText(`“${cardData.nickname}”`,textX,y,{maxWidth:rect.width-textX-24});}y+=34;context.fillStyle='#e4f1ed';context.font='14px sans-serif';context.fillText(cardData.id,textX,y);y+=24;context.fillText(cardData.phone,textX,y);y+=24;context.fillText(cardData.joined,textX,y);context.fillStyle='#cce8e0';context.font='12px sans-serif';context.textAlign='right';context.fillText(cardData.status,rect.width-20,rect.height-18);const mime=button.dataset.format==='jpeg'?'image/jpeg':'image/png';const link=document.createElement('a');link.download=`kta-choplug-no-brain-{{ $member->id }}.${button.dataset.format==='jpeg'?'jpg':'png'}`;link.href=canvas.toDataURL(mime,.94);link.click();}));
</script>
